import pytest
from candidate import sum_product

@pytest.mark.parametrize("numbers, expected", [
    ([], (0, 1)),
    ([1], (1, 1)),
    ([2], (2, 2)),
    ([1, 2], (3, 2)),
    ([1, 2, 3, 4], (10, 24)),
    ([0, -1, -2, -3], (-6, -1)),
    ([0, 1, 2], (3, 0)),
    ([0, 1, 2, 3], (6, 0)),
])
def test_sum_product_normalcases(numbers, expected):
    assert sum_product(numbers) == expected

def test_sum_product_empty_list():
    assert sum_product([]) == (0, 1)

def test_sum_product_list_with_one_element():
    assert sum_product([1]) == (1, 1)

def test_sum_product_list_with_two_elements():
    assert sum_product([1, 2]) == (3, 2)

def test_sum_product_list_with_zero():
    assert sum_product([0, 1, 2]) == (3, 0)

def test_sum_product_list_with_negative_numbers():
    assert sum_product([-1, -2, -3]) == (-6, -1)

def test_sum_product_list_with_mixed_positive_and_negative():
    assert sum_product([1, -1, 2, -2]) == (0, -1)

def test_sum_product_list_with_floats():
    assert sum_product([1.5, 2.5]) == (4.0, 6.25)

def test_sum_product_list_with_zero():
    assert sum_product([0, 1, 2, 3]) == (6, 0)

def test_sum_product_list_with_one_zero():
    assert sum_product([0, 1, 2, 3]) == (6, 0)

def test_sum_product_list_with_all_positive():
    assert sum_product([1, 2, 3, 4]) == (10, 24)

def test_sum_product_list_with_all_negative():
    assert sum_product([-1, -2, -3, -4]) == (-10, -1)
